import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { UserHttpService } from '../user-http.service';

@Injectable({ providedIn: 'root' })
export class AdminService {
  constructor(private http: HttpClient, private us: UserHttpService) {}

  inviteCompany(data: { companyName: string, email: string }) : Observable<any>{
    return this.http.post<any>(this.us.url + '/admin/invite', data, this.createOptions());
  }

  getAirports() : Observable<any>{
    return this.http.get<any[]>(this.us.url + '/airports', this.createOptions());
  }

  addAirport(data: any): Observable<any> {
    return this.http.post<any>(this.us.url + '/airports', data, this.createOptions());
  }

  updateAirport(id: string, data: any): Observable<any> {
    return this.http.put<any>(this.us.url + '/airports/' + id, data, this.createOptions());
  }

  deleteAirport(id: string): Observable<any> {
    return this.http.delete<any>(this.us.url + '/airports/' + id, this.createOptions());
  }

  private createOptions() {
    return {
      headers: new HttpHeaders({
        authorization: 'Bearer ' + this.us.get_token(),
        'Content-Type': 'application/json'
      })
    };
  }
}
